import users from './users.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'users_get_many',
      description: 'Look up multiple users by id in a single batch. Returns one line per requested id in request order, marking missing users without failing the entire batch.',
      inputSchema: {
        type: 'object',
        properties: {
          user_ids: {
            type: 'array',
            items: { type: 'string' },
            minItems: 1,
            maxItems: 5,
            uniqueItems: true,
          },
        },
        required: ['user_ids'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'users_get_many') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const { user_ids, ...rest } = args;

  if (Object.keys(rest).length > 0) {
    throw new Error('Unexpected arguments: only user_ids is allowed');
  }

  if (!Array.isArray(user_ids)) {
    throw new Error('user_ids must be an array');
  }

  if (user_ids.length === 0) {
    throw new Error('user_ids must be a non-empty array');
  }

  if (user_ids.length > 5) {
    throw new Error('user_ids must contain at most 5 entries');
  }

  for (const id of user_ids) {
    if (typeof id !== 'string') {
      throw new Error('user_ids must contain only strings');
    }
  }

  const seen = new Set();
  for (const id of user_ids) {
    if (seen.has(id)) {
      throw new Error(`Duplicate user id: ${id}`);
    }
    seen.add(id);
  }

  const lines = user_ids.map((id) => {
    const user = users[id];
    if (!user) {
      return `${id}: not found`;
    }
    return `${id}: ${user.name}`;
  });

  return {
    content: [{ type: 'text', text: lines.join('\n') }],
  };
}

